<?php declare(strict_types=1); namespace ProcessWire;
$root='';foreach(array_slice($argv,1) as $arg)if(str_starts_with($arg,'--root='))$root=rtrim(substr($arg,7),'/');
if($root===''||!is_file($root.'/index.php')||trim((string)@file_get_contents(dirname($root).'/.narzan-disposable'))!=='narzan-emulator-fixture-v1')throw new \RuntimeException('Explicit disposable fixture root required.');
