foreach(['a','b','c'] as $letter){$u=new User();$u->name='narzan-media-'.$letter.'-'.$suffix;$u->email=$u->name.'@example.test';$u->pass=bin2hex(random_bytes(20));$u->save();$accounts[]=$u;}[$a,$b,$c]=$accounts;
$users->setCurrentUser($a);$r=$m->startConversation($a,$b,'Synthetic media integration','realmedia_start_'.$suffix);$id=$r['conversation']['id'];$users->setCurrentUser($b);$m->acceptRequest($id,$b);$users->setCurrentUser($a);
$input=['filename'=>'synthetic.txt','mime_type'=>'text/plain','kind'=>'file','data_base64'=>base64_encode('Fixture media bytes')];
$message=$m->sendAttachment($id,$a,$input,'realmedia_small_'.$suffix);$aid=$message['attachment']['id'];$users->setCurrentUser($b);check($m->attachment($b,$aid)['data_base64']===$input['data_base64'],'two actors download');$users->setCurrentUser($c);denied(fn()=>$m->attachment($c,$aid));$users->setCurrentUser($a);
$stmt=$db->prepare('SELECT metadata,payload FROM messenger_attachments WHERE id=?');$stmt->execute([$aid]);$stored=$stmt->fetch(\PDO::FETCH_ASSOC);check(str_starts_with($stored['payload'],'menc:v1:')&&str_starts_with($stored['metadata'],'menc:v1:')&&!str_contains($stored['payload'],$input['data_base64']),'encrypted media and metadata');
check($m->sendAttachment($id,$a,$input,'realmedia_small_'.$suffix)['id']===$message['id'],'retry stable');$bad=$input;$bad['filename']='changed.txt';denied(fn()=>$m->sendAttachment($id,$a,$bad,'realmedia_small_'.$suffix));
$users->setCurrentUser($b);$m->markRead($id,$b,$message['id']);$m->setPresence($b,'invisible','Private synthetic status');$users->setCurrentUser($a);$chat=$m->conversation($id,$a);check($chat['other_last_read_message_id']===$message['id'],'real read cursor');check($chat['other_user']['presence']===['status'=>'offline','text'=>'','expires_at'=>0],'real invisible privacy');
