$auth=new MessengerMobileAuth($m);$verifier=str_repeat('x',64);$redirect='org.smnv.narzan.dev://auth/callback';$query=['redirect_uri'=>$redirect,'state'=>str_repeat('s',32),'code_challenge'=>rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='),'code_challenge_method'=>'S256','device_name'=>'Synthetic media integration'];$callback=$auth->approve($a,$query);parse_str((string)parse_url($callback,PHP_URL_QUERY),$parts);$tokens=$auth->exchange(['code'=>$parts['code'],'code_verifier'=>$verifier,'redirect_uri'=>$redirect]);
function request(string $resource,string $method,array $body=[]):array {global $root,$tokens;$c=curl_init('https://localhost:19443/messenger-api/v1/'.(str_contains($resource,'?')?str_replace('?','/?',$resource):$resource.'/'));curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>60,CURLOPT_CAINFO=>dirname($root).'/tls.crt',CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$tokens['access_token'],'Content-Type: application/json'],CURLOPT_CUSTOMREQUEST=>$method]);if($method==='POST')curl_setopt($c,CURLOPT_POSTFIELDS,json_encode($body,JSON_THROW_ON_ERROR));$raw=curl_exec($c);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);if(!is_string($raw))throw new \RuntimeException('Verified TLS transport failed');$result=json_decode($raw,true,512,JSON_THROW_ON_ERROR);check($status===200&&$result['ok']===true,'HTTP '.$resource);curl_close($c);return $result['result'];}
